import PropTypes from 'prop-types';

function VendorDetails(partnerId, orderSummary, local) {
  return {
    getRows() {
      return [
        {
          label: local('review-order.customer_info.customer_order'),
          value: orderSummary?.orderDetails.vendorOrderId ?? '-',
        },
      ];
    },
  };
}

VendorDetails.propTypes = {
  partnerId: PropTypes.string.isRequired,
  orderDetails: PropTypes.object,
  local: PropTypes.func.isRequired,
};

export default VendorDetails;
